<?php
namespace App\Http\Controllers;
use App\Models\{Transaccion,Cuenta,Categoria}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException;
class TransaccionController extends Controller {
 public function index(Request $r){ $q=Transaccion::with(['cuenta','categoria'])->orderByDesc('fecha')->orderByDesc('id'); if($r->filled('tipo')) $q->where('tipo',$r->tipo); if($r->filled('desde')) $q->whereDate('fecha','>=',$r->desde); if($r->filled('hasta')) $q->whereDate('fecha','<=',$r->hasta); $transacciones=$q->get(); return view('transacciones.index',compact('transacciones')); }
 public function create(){ return view('transacciones.create',['transaccion'=>new Transaccion,'cuentas'=>Cuenta::orderBy('nombre')->get(),'categorias'=>Categoria::orderBy('nombre')->get()]); }
 public function store(Request $r){ $d=$this->validated($r); DB::transaction(function() use($d){ $cuenta=Cuenta::whereKey($d['cuenta_id'])->lockForUpdate()->firstOrFail(); $this->applyBalance($cuenta,$d['tipo'],$d['monto']); Transaccion::create($d+['creado_por'=>auth()->user()->name]); }); return redirect()->route('transacciones.index')->with('success','Movimiento registrado y saldo actualizado.'); }
 public function edit(Transaccion $transaccion){ return view('transacciones.edit',['transaccion'=>$transaccion,'cuentas'=>Cuenta::orderBy('nombre')->get(),'categorias'=>Categoria::orderBy('nombre')->get()]); }
 public function update(Request $r,Transaccion $transaccion){ $d=$this->validated($r); DB::transaction(function() use($d,$transaccion){ $ids=collect([$transaccion->cuenta_id,$d['cuenta_id']])->unique()->sort()->values(); $cuentas=Cuenta::whereIn('id',$ids)->orderBy('id')->lockForUpdate()->get()->keyBy('id'); $anterior=$cuentas[$transaccion->cuenta_id]; $this->applyBalance($anterior,$transaccion->tipo,$transaccion->monto,true); $nueva=$cuentas[$d['cuenta_id']]; $this->applyBalance($nueva,$d['tipo'],$d['monto']); $transaccion->update($d); }); return redirect()->route('transacciones.index')->with('success','Movimiento actualizado y saldos recalculados.'); }
 public function destroy(Transaccion $transaccion){ DB::transaction(function() use($transaccion){ $cuenta=Cuenta::whereKey($transaccion->cuenta_id)->lockForUpdate()->firstOrFail(); $this->applyBalance($cuenta,$transaccion->tipo,$transaccion->monto,true); $transaccion->delete(); }); return back()->with('success','Movimiento eliminado y saldo revertido.'); }
 private function validated(Request $r): array { $d=$r->validate(['cuenta_id'=>'required|exists:cuentas,id','categoria_id'=>'required|exists:categorias,id','tipo'=>'required|in:ingreso,gasto','monto'=>'required|numeric|gt:0','fecha'=>'required|date','descripcion'=>'nullable|string|max:255']); $cat=Categoria::findOrFail($d['categoria_id']); if($cat->tipo!==$d['tipo']) throw ValidationException::withMessages(['categoria_id'=>'La categoría seleccionada no corresponde al tipo de movimiento.']); return $d; }
 private function applyBalance(Cuenta $cuenta,string $tipo,$monto,bool $revertir=false): void { $m=(float)$monto; $delta=$tipo==='ingreso'?$m:-$m; if($revertir) $delta=-$delta; $nuevo=(float)$cuenta->saldo+$delta; if($nuevo < -0.00001) throw ValidationException::withMessages(['monto'=>'El gasto supera el saldo disponible de la cuenta.']); $cuenta->saldo=round(max(0,$nuevo),2); $cuenta->save(); }
}
